create extension if not exists pgcrypto;
create type public.account_role as enum ('STUDENT','TEACHER','STAFF','ADMIN');
create type public.user_theme as enum ('DEFAULT','BLUE','AURORA','NEUTRAL');
create type public.post_section as enum ('FEED','PEDAGOGICAL','WALL','TRENDS');
create type public.post_type as enum ('GENERAL','ANNOUNCEMENT','PEDAGOGICAL','HEALTH','SAFETY','OPPORTUNITY','CULTURE','ENTREPRENEURSHIP');
create type public.alert_category as enum ('BULLYING','CYBERBULLYING','PREJUDICE','DISCRIMINATION','HARASSMENT','THREAT','ACCESSIBILITY','EMOTIONAL_SUPPORT','OTHER');
create type public.alert_urgency as enum ('GUIDANCE','ATTENTION','URGENT');
create type public.alert_status as enum ('RECEIVED','UNDER_REVIEW','CONTACT_ATTEMPTED','FORWARDED','RESOLVED','ARCHIVED');
create type public.report_status as enum ('OPEN','REVIEWING','DISMISSED','ACTION_TAKEN');
create type public.notification_type as enum ('COMMENT','LIKE','ANNOUNCEMENT','SUPPORT_UPDATE','ADMIN');

create table public.courses(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null unique,description text,active boolean not null default true,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique check(username ~ '^[a-z0-9._]{3,24}$'),full_name text,avatar_url text,bio text check(char_length(bio)<=500),course_id uuid references public.courses(id) on delete set null,class_name text,shift text,role public.account_role not null default 'STUDENT',theme public.user_theme not null default 'DEFAULT',high_contrast boolean not null default false,reduced_motion boolean not null default false,font_scale numeric not null default 1 check(font_scale in (1,1.15,1.3)),onboarding_completed boolean not null default false,suspended_at timestamptz,terms_accepted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id),title text check(char_length(title)<=120),content text not null check(char_length(content) between 1 and 5000),type public.post_type not null default 'GENERAL',section public.post_section not null default 'FEED',course_id uuid references public.courses(id) on delete set null,pinned boolean not null default false,official boolean not null default false,hidden_at timestamptz,hidden_by uuid references public.profiles(id),deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.post_images(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,image_url text not null,thumbnail_url text,imgchest_image_id text,alt_text text not null default '',position integer not null default 0 check(position between 0 and 3),created_at timestamptz not null default now(),unique(post_id,position));
create table public.post_likes(post_id uuid references public.posts(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,author_id uuid not null references public.profiles(id),content text not null check(char_length(content) between 1 and 1000),hidden_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.post_reports(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,reporter_id uuid not null references public.profiles(id),reason text not null,details text check(char_length(details)<=1000),status public.report_status not null default 'OPEN',reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now(),unique(post_id,reporter_id));
create sequence public.support_protocol_seq;
create table public.support_alerts(id uuid primary key default gen_random_uuid(),protocol text not null unique default ('ARCA-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.support_protocol_seq')::text,6,'0')),author_id uuid not null references public.profiles(id),category public.alert_category not null,urgency public.alert_urgency not null,description text not null check(char_length(description) between 20 and 5000),location text check(char_length(location)<=200),happened_at timestamptz,allow_contact boolean not null default true,status public.alert_status not null default 'RECEIVED',assigned_to uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table public.support_alert_notes(id uuid primary key default gen_random_uuid(),alert_id uuid not null references public.support_alerts(id) on delete cascade,author_id uuid not null references public.profiles(id),content text not null check(char_length(content) between 1 and 3000),internal boolean not null default true,created_at timestamptz not null default now());
create table public.support_alert_events(id uuid primary key default gen_random_uuid(),alert_id uuid not null references public.support_alerts(id) on delete cascade,actor_id uuid references public.profiles(id),event_type text not null,previous_status public.alert_status,new_status public.alert_status,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.profiles(id) on delete cascade,type public.notification_type not null,title text not null,body text not null,href text,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,resource_type text not null,resource_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());

create index posts_feed_idx on public.posts(section,pinned desc,created_at desc) where deleted_at is null;
create index comments_post_idx on public.comments(post_id,created_at); create index alerts_author_idx on public.support_alerts(author_id,created_at desc); create index alerts_queue_idx on public.support_alerts(status,urgency,created_at); create index notifications_recipient_idx on public.notifications(recipient_id,read_at,created_at desc); create index audit_created_idx on public.audit_logs(created_at desc);
create function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now(); return new; end$$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger posts_updated before update on public.posts for each row execute function public.set_updated_at(); create trigger comments_updated before update on public.comments for each row execute function public.set_updated_at(); create trigger alerts_updated before update on public.support_alerts for each row execute function public.set_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
